import React, { useEffect, useState, useMemo } from 'react';

// --- Badge Definitions and Thresholds (Extracted from BadgesPage logic) ---
const BADGE_THRESHOLDS = {
  volunteer: [
    { title: "Bronze Volunteer", desc: "Earned after 20 volunteer points", threshold: 20, key: "bronze_volunteer", 
      icon: "https://placehold.co/48x48/d97706/ffffff?text=B" }, // Placeholder for Bronze
    { title: "Silver Volunteer", desc: "Earned after 50 volunteer points", threshold: 50, key: "silver_volunteer", 
      icon: "https://placehold.co/48x48/94a3b8/ffffff?text=S" }, // Placeholder for Silver
    { title: "Gold Volunteer", desc: "Earned after 100 volunteer points", threshold: 100, key: "gold_volunteer", 
      icon: "https://placehold.co/48x48/f59e0b/ffffff?text=G" }, // Placeholder for Gold
  ],
  donor: [
    { title: "Silver Donor", desc: "Earned after 50 donor points", threshold: 50, key: "silver_donor", 
      icon: "https://placehold.co/48x48/475569/ffffff?text=S$" }, // Placeholder for Silver Donor
    { title: "Gold Donor", desc: "Earned after 100 donor points", threshold: 100, key: "gold_donor", 
      icon: "https://placehold.co/48x48/ca8a04/ffffff?text=G$" }, // Placeholder for Gold Donor
    { title: "Platinum Donor", desc: "Earned after 200 donor points", threshold: 200, key: "platinum_donor", 
      icon: "https://placehold.co/48x48/5b21b6/ffffff?text=P$" }, // Placeholder for Platinum Donor
  ],
};

// Function to calculate earned badges based on points
const calculateBadges = (volunteerPoints, donorPoints) => {
  const earnedBadges = [];

  // Check Volunteer Badges
  BADGE_THRESHOLDS.volunteer.forEach(badge => {
    if (volunteerPoints >= badge.threshold) {
      earnedBadges.push(badge);
    }
  });

  // Check Donor Badges
  BADGE_THRESHOLDS.donor.forEach(badge => {
    if (donorPoints >= badge.threshold) {
      earnedBadges.push(badge);
    }
  });

  return earnedBadges;
};

export default function AchievementsPanel({ token, me = {}, role = 'user', onViewNgo, setMsg }) {
  const [loading, setLoading] = useState(true);
  const [earnedBadges, setEarnedBadges] = useState([]);
  
  // NOTE: Assuming me.points represents volunteer points, and donorPoints is a separate field.
  // In a real app, ensure your 'me' object from the API provides separate point types.
  const volunteerPoints = me?.points || 0;
  const donorPoints = me?.donorPoints || 0; 
  const totalPoints = volunteerPoints + donorPoints;


  // 1. Client-Side Badge Calculation (Primary logic)
  useEffect(() => {
    // Calculate earned badges based on the user's current points
    const calculated = calculateBadges(volunteerPoints, donorPoints);
    setEarnedBadges(calculated);
    setLoading(false);
  }, [volunteerPoints, donorPoints]);


  // 2. Initial Data Fetch (Kept to simulate loading user data like NGO achievements, 
  // but *removed* the badge fetching as it's now calculated client-side)
  useEffect(() => {
    if (!token) return;

    // Simulate API fetch for initial data (NGO achievements, if applicable)
    const apiBase = process.env.REACT_APP_API || 'http://localhost:4000';
    const userUrl = role === 'NGO' ? `${apiBase}/api/ngo/achievements` : `${apiBase}/api/actions/achievements`;

    fetch(userUrl, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { 
        // We only care if the API *updates* the points, but we ignore badges from here.
        if (d) {
          console.log("Initial achievement data loaded:", d);
        }
      })
      .catch(err => { 
        console.error('Achievements load error', err); 
      })
      .finally(() => {
        // Since we are calculating badges client-side, we set loading state here.
        setLoading(false);
      });

    // NOTE: The fetch for /api/actions/user-badges was removed as badges are now computed.
  }, [token, role]);


  return (
    <div className="w-80 flex-shrink-0 p-4">
      <h3 className="text-xl font-semibold mb-4 text-gray-800">Your Achievements</h3>

      {/* Points Card */}
      <div className="bg-gradient-to-br from-sky-500 to-indigo-500 p-5 rounded-xl text-white text-center shadow-lg transform hover:scale-[1.02] transition duration-300">
        <div className="text-5xl font-extrabold mb-1">{totalPoints}</div>
        <div className="opacity-90 tracking-wider font-medium">TOTAL POINTS</div>
        <div className="text-xs mt-2 opacity-70">({volunteerPoints} Volunteer / {donorPoints} Donor)</div>
      </div>

      <div className="mt-6">
        <h4 className="text-lg font-semibold mb-3 text-gray-800">Badges Earned</h4>

        {loading && (
          <div className="text-sm text-gray-500">Calculating badges...</div>
        )}

        {!loading && earnedBadges.length === 0 && (
          <div className="p-4 rounded-xl bg-white text-gray-600 shadow-md border border-gray-100 text-sm">
            No badges yet — reach the first threshold (20 volunteer points) to earn Bronze!
          </div>
        )}

        {!loading && earnedBadges.length > 0 && (
          <div className="grid grid-cols-2 gap-3 mt-4">
            {earnedBadges.map((b) => (
              <div
                key={b.key}
                className="bg-white p-3 rounded-xl shadow-lg border border-gray-100 hover:shadow-xl transition duration-200 flex flex-col items-center"
              >
                {b.icon && (
                  <img
                    src={b.icon}
                    alt={b.title}
                    className="w-12 h-12 mb-2 object-contain rounded-full border-2 border-amber-400"
                  />
                )}

                <div className="font-bold text-sm text-gray-800 text-center">
                  {b.title}
                </div>

                <div className="text-xs text-gray-500 mt-0.5 text-center">
                  {b.desc.split(' ')[2]}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {onViewNgo && (
        <div className="mt-8">
          <button 
            onClick={() => onViewNgo()} 
            className="w-full py-3 rounded-xl bg-blue-600 text-white font-semibold hover:bg-blue-700 transition duration-200 shadow-lg shadow-blue-500/50"
          >
            View Hosting NGOs
          </button>
        </div>
      )}
    </div>
  );
}
